def generate_stats(rarity):
    if rarity == "ULTRA RARE":
        total_points = 20
    elif rarity == "RARE":
        total_points = 18
    elif rarity == "UNCOMMON":
        total_points = 17
    else:  # rarity == "COMMON"
        total_points = 15

    min_points = 1
    stats = ['STR', 'INT', 'PDEF', 'MDEF', 'AGI', 'CON']
    stat_values = {stat: min_points for stat in stats}
    remaining_points = total_points - (min_points * len(stats))

    while remaining_points > 0:
        stat = random.choice(stats)
        stat_values[stat] += 1
        remaining_points -= 1

    return stat_values
